// Chứng từ mới trong ngày có giá trị vượt trội hẳn so với trung bình lịch sử — KHÔNG khẳng
// định là sai, chỉ gắn cờ để kế toán liếc lại (khả năng gõ nhầm thêm số 0, hoặc đơn thật sự
// lớn cần xác nhận). Việc quyết định đúng/sai là của người, không phải của rule này.
const d = $json;
const items = d.items || [];
const vnd = n => new Intl.NumberFormat('vi-VN').format(n || 0) + '₫';
const SOURCE_LABEL = { sales: 'Bán hàng', purchase: 'Mua hàng' };

const rows = items.map(v => `<tr><td>${SOURCE_LABEL[v.source] || v.source}</td><td>${v.voucher_no || '—'}</td><td>${v.partner_name}</td><td align="right"><b>${vnd(v.total_amount)}</b></td><td align="right">${v.multiple}× TB</td></tr>`).join('');

const html = `<h2>🚨 ${items.length} chứng từ giá trị bất thường (>${d.multiplier}× trung bình)</h2>`
  + `<p>Không chắc là sai — chỉ đáng để xem lại trước khi khoá sổ.</p>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><th>Loại</th><th>Số chứng từ</th><th>Đối tác</th><th>Số tiền</th><th>So với TB</th></tr>${rows}</table>`
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `🚨 ${items.length} chứng từ giá trị bất thường cần xem lại`,
  email_html: html
} };
